package com.primehr.security;
import com.primehr.integration.administrative.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Component;
@Component public class SuccessionPlanningPermissionGuard {
 public static final String CAREER_PATH="primehr.succession-career-path",CRITICAL_POSITION="primehr.succession-critical-position",POOL="primehr.succession-pool",READINESS="primehr.succession-readiness",DEVELOPMENT="primehr.succession-development",CONTINUITY="primehr.succession-continuity",REPORT="primehr.succession-report",ANALYTICS="primehr.succession-analytics"; private final AdministrativeAuthorizationClient client;
 public SuccessionPlanningPermissionGuard(AdministrativeAuthorizationClient client){this.client=client;}
 public PermissionDataScope require(String feature,PrimeHrAction action,String token){EffectiveFeaturePermission p=client.resolve(feature,token);boolean ok=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case PUBLISH->p.canPublish();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case FINALIZE->p.canFinalize();case ARCHIVE->p.canDelete();default->false;};if(!ok)throw new AccessDeniedException("Succession planning permission is required");PermissionDataScope scope=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if((feature.equals(CAREER_PATH)||feature.equals(ANALYTICS))&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("This succession feature requires Agency Wide scope");if((feature.equals(CRITICAL_POSITION)||feature.equals(CONTINUITY))&&scope!=PermissionDataScope.ASSIGNED_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Critical positions and continuity records require Assigned Records or Agency Wide scope");return scope;}
}
